async function readFileBase64(file) { return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = reject; reader.readAsDataURL(file); }); }
async function uploadDocumentTemplate(file) { if (!file) return; if (DEMO_MODE) return showToast('기관 양식 분석은 개인정보 보호를 위해 Windows EXE 또는 로컬 서버에서 사용하세요.'); const status = $('#documentTemplateStatus'); status.textContent = '양식 구조를 이 PC에서 분석하는 중…'; try { const dataBase64 = await readFileBase64(file); const response = await fetch('/api/document-templates', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ fileName: file.name, dataBase64 }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error || 'document_template_upload_failed'); state.uploadedTemplate = { ...result.analysis, ...result.template }; state.uploadedTemplates = [state.uploadedTemplate, ...state.uploadedTemplates.filter((item) => item.id !== state.uploadedTemplate.id)]; state.documentTemplateId = state.uploadedTemplate.id; state.documentId = null; state.documentDraft = null; renderDocumentForm(); status.textContent = result.analysis.ready ? `로컬 템플릿 저장됨 · ${result.analysis.fieldCount}개 항목` : '태그 없음 · 원본 양식에 {{항목}} 태그 필요'; $('#documentPreview').innerHTML = `<div class="document-placeholder"><span>✓</span><h3>${escapeHtml(result.analysis.fileName)} 분석 완료</h3><p>${result.analysis.fieldCount ? `${result.analysis.fieldCount}개 입력 항목을 발견했습니다.` : '태그가 없어 항목 확인이 필요합니다.'}<br /><b>기록에서 채우기</b> 또는 직접 입력 후 초안을 만드세요.</p></div>`; $('#documentReviewStatus').textContent = result.analysis.ready ? '양식 항목 확인 완료 · 생성 전 검토 필요' : '태그가 없습니다 · 원본에 {{항목}} 태그를 추가하세요.'; showToast(result.analysis.ready ? '기관 양식을 로컬 템플릿으로 저장했습니다.' : '양식은 저장했지만 입력 태그가 없어 매핑이 필요합니다.'); } catch (error) { status.textContent = '분석 실패'; showToast(`기관 양식을 분석하지 못했습니다: ${error.message}`); } }
