async function generateDocument() { const fields = documentFieldsFromForm(); const templateId = state.documentTemplateId; const source = await getDocumentSource(); try { if (state.uploadedTemplate) { if (!state.uploadedTemplate.fields?.length) return showToast('이 양식에는 {{항목명}} 태그가 없습니다. 기관 양식에 입력 위치 태그를 추가한 뒤 다시 업로드하세요.'); if (state.uploadedTemplate.ready === false) return showToast('양식 태그가 문서 구조상 분리되어 있습니다. 태그를 한 덩어리로 입력한 뒤 다시 업로드하세요.'); state.documentDraft = buildUploadedDocumentDraft({ template: state.uploadedTemplate, fields, source }); } else { const payload = DEMO_MODE ? { draft: buildDemoDocumentDraft({ templateId, fields, source }) } : await fetch('/api/documents/preview', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ templateId, fields, source: source.id ? { id: source.id, rawText: source.rawText, contextText: source.contextText, draft: source.draft } : {} }) }).then(async (response) => { const result = await response.json(); if (!response.ok) throw new Error(result.error || 'document_preview_failed'); return result; }); state.documentDraft = payload.draft; } state.documentId = null; renderDocumentPreview(); showToast(state.documentDraft.missing.length ? `초안을 만들었습니다. 필수 항목 ${state.documentDraft.missing.length}개를 확인하세요.` : state.uploadedTemplate ? '기관 양식에 값을 매핑했습니다. 원본 서식을 유지한 결과물을 확인하세요.' : '기관 문서 초안을 만들었습니다.'); } catch (error) { showToast(`문서 초안을 만들지 못했습니다: ${error.message}`); } }
function syncDocumentPreview() { if (!state.documentDraft) return; $$('#documentPreview [data-doc-section]').forEach((field) => { const section = state.documentDraft.sections.find((item) => item.id === field.dataset.docSection); if (section) section.content = field.value; }); }
function renderDocumentPreview() { const draft = state.documentDraft; if (!draft) return; $('#documentPreview').innerHTML = `<header class="paper-header"><p>${escapeHtml(draft.templateLabel)}</p><h1>${escapeHtml(draft.title)}</h1><small>자료 출처: ${escapeHtml(draft.sourceType)} · ${new Date(draft.generatedAt).toLocaleString('ko-KR')}</small></header>${draft.sections.map((section) => `<section class="paper-section"><div class="paper-section-heading"><h3>${escapeHtml(section.heading)}</h3><span>검토</span></div><textarea data-doc-section="${escapeHtml(section.id)}">${escapeHtml(section.content)}</textarea></section>`).join('')}<div class="paper-footer"><span>담당자 검토 후 공식 문서로 확정하세요.</span><b>DAWITH · LOCAL DRAFT</b></div>`; const missing = draft.missing || []; $('#documentReviewStatus').textContent = missing.length ? `필수 항목 ${missing.length}개 미입력 · ${missing.join(', ')}` : '필수 항목 입력 완료 · 내용 검토 필요'; $('#documentReviewStatus').classList.toggle('ready', !missing.length); updateDocumentExportLabels(); }
async function saveDocument() { syncDocumentPreview(); if (!state.documentDraft) return showToast('먼저 문서 초안을 만들어주세요.'); const payload = { templateId: state.documentDraft.templateId, title: state.documentDraft.title, payload: state.documentDraft }; try { if (DEMO_MODE) { const documents = demoRead(demoDocumentsKey, []); const saved = { id: state.documentId || `demo_document_${Date.now()}`, ...payload, createdAt: state.documentId ? (documents.find((item) => item.id === state.documentId)?.createdAt || new Date().toISOString()) : new Date().toISOString(), updatedAt: new Date().toISOString() }; const index = documents.findIndex((item) => item.id === saved.id); if (index >= 0) documents[index] = saved; else documents.unshift(saved); demoWrite(demoDocumentsKey, documents); state.documents = documents; state.documentId = saved.id; } else { const endpoint = state.documentId ? `/api/documents/${encodeURIComponent(state.documentId)}` : '/api/documents'; const response = await fetch(endpoint, { method: state.documentId ? 'PATCH' : 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }); if (!response.ok) throw new Error('document_save_failed'); const result = await response.json(); state.documentId = result.document.id; state.documents = await fetch('/api/documents').then((response) => response.json()).then((result) => result.documents); } renderSavedDocuments(); renderRecentDocuments(); showToast('검토한 문서를 이 PC에 저장했습니다.'); } catch (error) { showToast(`문서를 저장하지 못했습니다: ${error.message}`); } }
async function openDocument(documentId) { try { const document = DEMO_MODE ? demoRead(demoDocumentsKey, []).find((item) => item.id === documentId) : await fetch(`/api/documents/${encodeURIComponent(documentId)}`).then(async (response) => response.ok ? (await response.json()).document : null); if (!document) throw new Error('document_not_found'); state.documentId = document.id; state.documentTemplateId = document.templateId; state.uploadedTemplate = null; if (!DEMO_MODE && document.templateId.startsWith('uploaded:')) { const templateResponse = await fetch(`/api/document-templates/${encodeURIComponent(document.templateId)}`); if (templateResponse.ok) state.uploadedTemplate = (await templateResponse.json()).template; } state.documentDraft = document.payload; renderDocumentForm(); renderDocumentPreview(); navigate('documents'); showToast('저장된 문서를 열었습니다.'); } catch (error) { showToast(`문서를 열지 못했습니다: ${error.message}`); } }
async function exportDocument(format = 'docx') { syncDocumentPreview(); if (!state.documentDraft) return showToast('먼저 문서 초안을 만들어주세요.'); if (!state.documentId) await saveDocument(); if (!state.documentId) return; if (!DEMO_MODE) { const response = await fetch(`/api/documents/${encodeURIComponent(state.documentId)}/export?format=${format}`); if (!response.ok) return showToast('문서를 내보내지 못했습니다.'); const extension = state.uploadedTemplate?.format || (format === 'docx' ? 'docx' : format === 'markdown' ? 'md' : 'html'); downloadBlob(await response.blob(), `dawith-document-${state.documentId}.${extension}`); showToast(`${extension.toUpperCase()} 파일을 내보냈습니다.`); return; } if (format === 'markdown') { const text = `# ${state.documentDraft.title}\n\n${state.documentDraft.sections.map((section) => `## ${section.heading}\n\n${section.content}`).join('\n\n')}`; downloadBlob(new Blob([text], { type: 'text/markdown' }), `dawith-document-${Date.now()}.md`); } else { const html = `<html lang="ko"><meta charset="utf-8"><title>${escapeHtml(state.documentDraft.title)}</title><style>body{font-family:Arial;max-width:760px;margin:40px auto;line-height:1.8}h1{color:#205b47}pre{white-space:pre-wrap}</style><h1>${escapeHtml(state.documentDraft.title)}</h1>${state.documentDraft.sections.map((section) => `<h2>${escapeHtml(section.heading)}</h2><pre>${escapeHtml(section.content)}</pre>`).join('')}`; downloadBlob(new Blob([html], { type: 'text/html' }), `dawith-document-${Date.now()}.html`); } showToast('문서를 이 PC에 내보냈습니다.'); }

