async function refreshRecords() { const query = $('#recordSearch')?.value.trim().toLowerCase() || ''; const kind = $('#recordKind')?.value || ''; if (DEMO_MODE) { state.records = demoRead(demoStorageKey, []).filter((record) => (!kind || record.kind === kind) && (!query || JSON.stringify(record).toLowerCase().includes(query))); renderRecent(); renderRecords(); return; } const params = new URLSearchParams(); if (query) params.set('q', query); if (kind) params.set('kind', kind); const response = await fetch(`/api/records?${params}`); state.records = (await response.json()).records; renderRecent(); renderRecords(); }
